		writeLock(t, ws, `{"token":"t","pid":1,"created_at":"x"}`)
		r := buildStatus(t, ws, statusOpts(nil, nil))
		if hasIssue(r, IssueSessionStateUnsupported) == nil {
			t.Fatalf("expected session-state-unsupported, got %v", issueCodes(r))
