func testReparentExclusionLiveAndUndecodableSessions(t *testing.T) {
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		pr1Token, err := internal.CreateDirectSession(f.FeaturePath, internal.DirectSessionRecord{
