		}

		pr2Token, err := internal.CreateDirectSession(f.FeaturePath, internal.DirectSessionRecord{
			Feature: f.Feature, Name: "pr2", GitBranch: "feat-pr2", Path: internal.WorktreePath(f.Feature, "pr2"),
		})
