		})
		stdout, _, _ := f.Run(f.Feature, "pr2", "--onto", "master", "--no-fetch", "--plan", "--json")
		var allowed internal.ReparentPlan
		if err := json.Unmarshal([]byte(stdout), &allowed); err != nil {
